import{_ as o,W as l,s as i,u as d,ah as u,I as a,w as s,Z as n,A as e}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const x=JSON.parse('{"title":"如何在 Linux 命令行操作 PDF | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 命令行操作 PDF | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 命令行操作 PDF | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 命令行操作 PDF | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190808 How to manipulate PDFs on Linux","title":"如何在 Linux 命令行操作 PDF","tag":"201908"},"relativePath":"201908/20190808 How to manipulate PDFs on Linux.md","filePath":"[post].md"}'),r={name:"201908/20190808 How to manipulate PDFs on Linux.md"};function g(f,t,h,c,m,b){const p=l("Link");return d(),i("div",null,[t[19]||(t[19]=u(`<h1 id="如何在-linux-命令行操作-pdf" tabindex="-1">如何在 Linux 命令行操作 PDF <a class="header-anchor" href="#如何在-linux-命令行操作-pdf" aria-label="Permalink to 如何在 Linux 命令行操作 PDF">​</a></h1><blockquote><p>pdftk 命令提供了许多处理 PDF 的命令行操作，包括合并页面、加密文件、添加水印、压缩文件，甚至还有修复 PDF。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/15/110119x6sjnjs6s22srnje.jpg" alt=""></p><p>虽然 PDF 通常被认为是相当稳定的文件，但在 Linux 和其他系统上你可以做很多处理。包括合并、拆分、旋转、拆分成单页、加密和解密、添加水印、压缩和解压缩，甚至还有修复。 <code>pdftk</code> 命令能执行所有甚至更多操作。</p><p>“pdftk” 代表 “PDF 工具包”（PDF tool kit），这个命令非常易于使用，并且可以很好地操作 PDF。例如，要将独立的文件合并成一个文件，你可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pdftk pg1.pdf pg2.pdf pg3.pdf pg4.pdf pg5.pdf cat output OneDoc.pdf</span></span></code></pre></div><p><code>OneDoc.pdf</code> 将包含上面显示的所有五个文档，命令将在几秒钟内运行完毕。请注意，<code>cat</code> 选项表示将文件连接在一起，<code>output</code> 选项指定新文件的名称。</p><p>你还可以从 PDF 中提取选定页面来创建单独的 PDF 文件。例如，如果要创建仅包含上面创建的文档的第 1、2、3 和 5 页的新 PDF，那么可以执行以下操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pdftk OneDoc.pdf cat 1-3 5 output 4pgs.pdf</span></span></code></pre></div><p>另外，如果你想要第 1、3、4 和 5 页（总计 5 页），我们可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pdftk OneDoc.pdf cat 1 3-end output 4pgs.pdf</span></span></code></pre></div><p>你可以选择单独页面或者页面范围，如上例所示。</p><p>下一个命令将从一个包含奇数页（1、3 等）的文件和一个包含偶数页（2、4 等）的文件创建一个整合文档：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pdftk A=odd.pdf B=even.pdf shuffle A B output collated.pdf</span></span></code></pre></div><p>请注意，<code>shuffle</code> 选项使得能够完成整合，并指示文档的使用顺序。另请注意：虽然上面建议用的是奇数/偶数页，但你不限于仅使用两个文件。</p><p>如果要创建只能由知道密码的收件人打开的加密 PDF，可以使用如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pdftk prep.pdf output report.pdf user_pw AsK4n0thingGeTn0thing</span></span></code></pre></div><p>选项提供 40（<code>encrypt_40bit</code>）和 128（<code>encrypt_128bit</code>）位加密。默认情况下使用 128 位加密。</p><p>你还可以使用 <code>burst</code> 选项将 PDF 文件分成单个页面：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pdftk allpgs.pdf burst</span></span>
<span class="line"><span>$ ls -ltr *.pdf | tail -5</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   22933 Aug  8 08:18 pg_0001.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23773 Aug  8 08:18 pg_0002.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23260 Aug  8 08:18 pg_0003.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23435 Aug  8 08:18 pg_0004.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23136 Aug  8 08:18 pg_0005.pdf</span></span></code></pre></div>`,20)),a("p",null,[t[1]||(t[1]=a("code",null,"pdftk",-1)),t[2]||(t[2]=s(" 命令使得合并、拆分、重建、加密 PDF 文件非常容易。要了解更多选项，请查看 ")),n(p,{href:"https://www.pdflabs.com/docs/pdftk-cli-examples/"},{default:e(()=>t[0]||(t[0]=[s("PDF 实验室")])),_:1}),t[3]||(t[3]=s("中的示例页面。"))]),t[20]||(t[20]=a("hr",null,null,-1)),a("p",null,[t[5]||(t[5]=s("via: ")),n(p,{href:"https://www.networkworld.com/article/3430781/how-to-manipulate-pdfs-on-linux.html"},{default:e(()=>t[4]||(t[4]=[s("https://www.networkworld.com/article/3430781/how-to-manipulate-pdfs-on-linux.html")])),_:1})]),a("p",null,[t[10]||(t[10]=s("作者：")),n(p,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>t[6]||(t[6]=[s("Sandra Henry-Stocker")])),_:1}),t[11]||(t[11]=s(" 选题：")),n(p,{href:"https://github.com/lujun9972"},{default:e(()=>t[7]||(t[7]=[s("lujun9972")])),_:1}),t[12]||(t[12]=s(" 译者：")),n(p,{href:"https://github.com/geekpi"},{default:e(()=>t[8]||(t[8]=[s("geekpi")])),_:1}),t[13]||(t[13]=s(" 校对：")),n(p,{href:"https://github.com/wxy"},{default:e(()=>t[9]||(t[9]=[s("wxy")])),_:1})]),a("p",null,[t[16]||(t[16]=s("本文由 ")),n(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>t[14]||(t[14]=[s("LCTT")])),_:1}),t[17]||(t[17]=s(" 原创编译，")),n(p,{href:"https://linux.cn/"},{default:e(()=>t[15]||(t[15]=[s("Linux中国")])),_:1}),t[18]||(t[18]=s(" 荣誉推出"))])])}const v=o(r,[["render",g]]);export{x as __pageData,v as default};
